 const start={x:4,y:4};g.spawn={x:start.x*T+24,y:start.y*T+24};const distances=Array(g.map.length).fill(-1),queue=[[start.x,start.y]];distances[A.tileIndex(start.x,start.y)]=0;for(let i=0;i<queue.length;i++){const [x,y]=queue[i];for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]])if(A.walk(x+dx,y+dy)&&distances[A.tileIndex(x+dx,y+dy)]<0){distances[A.tileIndex(x+dx,y+dy)]=distances[A.tileIndex(x,y)]+1;queue.push([x+dx,y+dy]);}}
