function cast(a,m){const target=A.nearTarget(a),angle=target?Math.atan2(target.y-a.y,target.x-a.x):a.aim??Math.PI/2,damage=attackPower(a,m),kind=m.kind;if(['sleep','stun','heal','shield','buff','haste','slow','poison','blink','mimic','metronome','leech','firezone'].includes(m.mode))a.replicaReady=false;
 if(m.mode==='blink'){const direction=Math.hypot(a.vx||0,a.vy||0)>8?Math.atan2(a.vy,a.vx):angle+Math.PI;for(let i=0;i<8;i++)A.move(a,Math.cos(direction)*20,Math.sin(direction)*20);a.inv=Math.max(a.inv,.6);A.fx('psychic',a.x,a.y,1.6,.5);return;}
 if(m.mode==='metronome'){cast(a,{name:'Metrónomo',mode:A.pick(['beam','fan','shield','heal']),kind:'psychic',power:60,mana:0,cool:0});return;}
 if(m.mode==='mimic'){const copied=target&&S[target.id]?.moves?.[1];if(copied&&!['mimic','metronome'].includes(copied.mode)){cast(a,{...copied,mana:0});A.toast('Transformación copió '+copied.name+'.');}else{a.shield=3;A.fx('psychic',a.x,a.y,2,.5);}return;}
 if(m.mode==='sleep'){statusNear(a,'sleep',3,235);playSound('cast');return;}
 if(m.mode==='stun'){if([25,26].includes(a.id))a.haste=2;statusNear(a,'stun',1.8,195);A.fx('discharge',a.x,a.y,3,.6);return;}
 if(m.mode==='heal'){a.hp=Math.min(a.max,a.hp+a.max*.28*(a.healPower||1));A.fx('water',a.x,a.y,3,.6);playSound('heal');return;}
 if(m.mode==='shield'){a.shield=4;a.hp=Math.min(a.max,a.hp+a.max*.05);A.fx('water',a.x,a.y,2.8,.6);return;}
 if(m.mode==='buff'){a.buff=6;A.fx('star',a.x,a.y,2,.6);return;}
 if(m.mode==='haste'){a.haste=6;a.inv=Math.max(a.inv,.7);return;}
 if(m.mode==='slow'||m.mode==='poison'){statusNear(a,m.mode,m.mode==='slow'?5:7,230);return;}
 if(m.mode==='leech'||m.mode==='firezone'){const t=target||{x:a.x+Math.cos(angle)*140,y:a.y+Math.sin(angle)*140};zones.push({id:Math.random().toString(36),owner:a.pid,x:t.x,y:t.y,r:m.mode==='leech'?130:150,kind,mode:m.mode,life:7,tick:0,damage:damage*.25});A.fx(kind,t.x,t.y,3,.5);return;}
 if(m.mode==='dash'){a.burst=.24;a.inv=.55;a.vx=Math.cos(angle)*680;a.vy=Math.sin(angle)*680;for(const e of A.enemies)if(e.hp>0&&dist(a,e)<190&&Math.cos(Math.atan2(e.y-a.y,e.x-a.x)-angle)>.4&&A.clearLine(a,e))A.hurt(e,damage,a);playSound('cast');return;}
 if(m.mode==='melee'||m.mode==='cleave'){A.fx(kind,a.x+Math.cos(angle)*45,a.y+Math.sin(angle)*45,1.4,.3);for(const e of A.enemies)if(e.hp>0&&dist(a,e)<(m.mode==='cleave'?155:110)&&Math.cos(Math.atan2(e.y-a.y,e.x-a.x)-angle)>.1&&A.clearLine(a,e))A.hurt(e,damage,a,{effect:m.mode});playSound('hit');return;}
 if(m.mode==='beam'){A.effects.push({line:true,kind,x:a.x,y:a.y,ex:a.x+Math.cos(angle)*780,ey:a.y+Math.sin(angle)*780,life:.4,total:.4,size:1});for(const e of A.enemies)if(e.hp>0&&dist(a,e)<850&&A.clearLine(a,e)){const ea=Math.atan2(e.y-a.y,e.x-a.x);if(Math.abs(Math.atan2(Math.sin(ea-angle),Math.cos(ea-angle)))<.2)A.hurt(e,damage,a,{effect:'beam'});}playSound('cast');return;}
 if(m.mode==='cone'){channels.push({owner:a.pid,angle,damage:damage*.22,life:.58,tick:0});playSound('cast');return;}
 const n=['fan','cone','wave'].includes(m.mode)?(m.mode==='wave'?7:5):1;for(let i=0;i<n;i++)A.fire(a,angle+(i-(n-1)/2)*.14,m.mode==='wave'?300:440,damage*(n>1?.7:1),kind,a.x+Math.cos(angle)*22,a.y+Math.sin(angle)*22,{effect:m.mode,size:m.mode==='cone'?1.4:1});playSound('cast');}
A.attack=function(a){if(a.cool>0||a.action||a.burst>0||a.down||a.sleep>0)return;const m=movesFor(a)[0];a.cool=(a.buff>0?.27:m.cool)*(1-(a.cdr||0));const target=A.nearTarget(a),angle=target?Math.atan2(target.y-a.y,target.x-a.x):a.aim??Math.PI/2;if(Math.hypot(a.vx,a.vy)<8)A.face(a,Math.cos(angle),Math.sin(angle));A.action(a,m.mode==='melee'||m.mode==='cleave'?'Attack':'Shoot',()=>cast(a,m),a.cool*.93);};
A.special=function(a,key){if(a[key]>0||a.action||a.down||a.sleep>0)return;const m=movesFor(a)[key==='q'?1:2]||movesFor(a)[1];if(key==='e'&&a.level<8){if(a.pid===A.myPid)A.toast('El tercer movimiento se desbloquea al nivel 8.');a.e=.8;return;}if(!spend(a,m.mana))return;a[key]=m.cool*(1-(a.cdr||0));A.action(a,key==='q'?'Charge':'Shoot',()=>cast(a,m),.48);};
A.classSkill=function(a){if(a.rskill>0||a.down||a.sleep>0)return;const c=C[a.job];if(!spend(a,c.cost))return;a.rskill=c.cool*(1-(a.cdr||0));const friends=A.active().filter(b=>dist(a,b)<350),targets=A.enemies.filter(e=>e.hp>0&&dist(a,e)<470);const branch=a.branch||c.branches[0];
 switch(a.job){case 'guardian':for(const b of friends)b.shield=branch==='Bastión'?6:4;if(branch==='Centinela')statusNear(a,'stun',2,250);break;
 case 'striker':if(branch==='Duelista'){const t=A.nearTarget(a);if(t){const angle=Math.atan2(t.y-a.y,t.x-a.x);a.burst=.2;a.inv=.5;a.vx=Math.cos(angle)*640;a.vy=Math.sin(angle)*640;A.hurt(t,a.damage*3.5,a);}}else{a.buff=7;a.frenzyLeech=7;}break;
 case 'support':for(const b of friends){b.hp=Math.min(b.max,b.hp+b.max*(branch==='Clínico'?.33:.22)*(a.healPower||1));b.poison=0;b.sleep=0;b.burn=0;b.slow=0;if(branch==='Protector')b.shield=3;}A.fx('water',a.x,a.y,5,.8);playSound('heal');break;
 case 'explorer':A.g.stairsKnown=true;for(const trap of A.g.traps){trap.revealed=true;if(branch==='Trampero'&&dist(a,trap)<400)trap.armed=false;}if(branch==='Trampero')zones.push({id:'snare'+A.clock,owner:a.pid,x:a.x,y:a.y,r:160,mode:'snare',kind:'leaf',damage:a.damage*.2,life:9,tick:0});break;
 case 'mage':if(branch==='Canalizador'){a.shield=4;a.mp=Math.min(a.maxMp,a.mp+20);}for(let i=0;i<(branch==='Artillero'?16:10);i++)A.fire(a,i*Math.PI*2/(branch==='Artillero'?16:10),360,a.damage*1.7*(a.skillPower||1),'psychic');break;
 case 'assassin':if(branch==='Saboteador')zones.push({id:'bomb'+A.clock,owner:a.pid,x:a.x,y:a.y,r:210,mode:'firezone',kind:'poison',damage:a.damage*.55,life:5,tick:0});else{a.inv=1.3;a.haste=4;const t=A.nearTarget(a);if(t){const angle=Math.atan2(t.y-a.y,t.x-a.x);A.move(a,Math.cos(angle)*Math.min(dist(a,t)-40,180),Math.sin(angle)*Math.min(dist(a,t)-40,180));A.hurt(t,a.damage*4,a);}}break;
 case 'alchemist':if(branch==='Transmutador'){const item=['oran_berry','potion'].find(k=>a.bag[k]>0);if(item){a.bag[item]--;for(const b of friends){b.hp=Math.min(b.max,b.hp+40*(a.healPower||1));b.mp=Math.min(b.maxMp,b.mp+20);}}else a.mp=Math.min(a.maxMp,a.mp+12);}else{const t=A.nearTarget(a)||a;zones.push({id:'acid'+A.clock,owner:a.pid,x:t.x,y:t.y,r:210,mode:'firezone',kind:'poison',damage:a.damage*.5,life:7,tick:0});}break;
 case 'engineer':{const count=branch==='Mecánico'?2:1;for(let i=0;i<count;i++)helpers.push({id:100,owner:a.pid,x:a.x+(i?65:-65),y:a.y,life:branch==='Mecánico'?9:14,cool:0,stationary:true,damage:a.damage*(count===2?.65:1.2),dir:0,anim:0});break;}
 case 'bard':if(branch==='Discordante'){for(const e of targets){e.slow=6;e.sleep=1.5;}}else for(const b of friends){b.q=Math.max(0,b.q-3);b.e=Math.max(0,b.e-3);b.mp=Math.min(b.maxMp,b.mp+18);b.haste=4;}break;
 case 'chronomancer':if(branch==='Acelerador'){for(const b of friends){b.q=0;b.e=0;b.dash=0;b.haste=5;}}else{for(const e of targets){e.slow=8;e.stun=1;}a.q=Math.max(0,a.q-3);a.e=Math.max(0,a.e-3);}break;
 case 'summoner':{const count=branch==='Enjambre'?2:1;for(let i=0;i<count;i++)helpers.push({id:a.id,owner:a.pid,x:a.x+(i?50:-50),y:a.y+35,life:count===2?10:15,cool:0,stationary:false,damage:a.damage*(count===2?.55:.9),dir:a.dir,anim:0,heals:branch==='Guía'});break;}}
 A.fx(a.job==='support'?'water':'star',a.x,a.y,3,.7);playSound('class');};
A.hurt=function(e,d,owner,projectile){if(e.hp<=0)return;const alive=e.hp>0,oldLoot=A.loot.length;if(owner){d*=clamp(1+(owner.level-e.level)*.055,.45,1.6);owner.combat=4;if(projectile?.criticalReplica??owner.replicaReady){owner.replicaReady=false;const target=A.enemies.find(o=>o!==e&&o.hp>0&&dist(e,o)<300)||e;A.fire(owner,Math.atan2(target.y-owner.y,target.x-owner.x),420,d*.45,'star',owner.x,owner.y,{effect:'replica'});}if(owner.leech||owner.frenzyLeech>0)owner.hp=Math.min(owner.max,owner.hp+Math.min(e.hp,d)*((owner.leech||0)+(owner.frenzyLeech>0?.08:0)));if(['fire','flame'].includes(projectile?.kind))e.burn=4;if(projectile?.kind==='poison')e.poison=4;if(projectile?.effect==='push'||projectile?.effect==='wave'){const dx=e.x-owner.x,dy=e.y-owner.y,dd=Math.hypot(dx,dy)||1;A.move(e,dx/dd*28,dy/dd*28);e.slow=projectile.effect==='wave'?2:0;}if(projectile?.effect==='chain'||owner.synergies?.includes('Dínamo')){const other=A.enemies.find(o=>o!==e&&o.hp>0&&dist(e,o)<150);if(other){old.hurt(other,d*.45);A.fx('spark',other.x,other.y,.9,.3);}}}e.sleep=0;old.hurt(e,d);A.loot=A.loot.slice(0,oldLoot);if(alive&&e.hp<=0&&!e.boss){const extra=Math.max(0,e.level*2-(12+Math.floor(A.g.floor/4)));for(const a of A.players)A.gainXP(a,extra);}playSound(e.hp<=0?'loot':'hit');};
A.damage=function(a,d,kind='hit',enemyLevel,effect){const previous=a.hp;const level=enemyLevel||Math.round(3+A.g.floor*.72),mult=clamp(1+(level-a.level)*.055,.45,1.8);old.damage(a,d*mult*(1-(a.armor||0)),kind);if(a.hp<previous){if(effect==='poison')a.poison=5;if(effect==='stun')a.slow=2;}playSound('hurt');};
A.enemyStep=function(e,dt){if(e.hp<=0){old.enemyStep(e,dt);return;}for(const k of ['sleep','slow','poison','burn'])e[k]=Math.max(0,(e[k]||0)-dt);if((e.poison>0||e.burn>0)&&(e.dotTime=(e.dotTime||0)+dt)>=1){e.dotTime=0;A.hurt(e,Math.max(2,e.max*.018));if(e.hp<=0)return;}if(e.sleep>0){e.moving=false;e.warning=null;e.windup=0;return;}if(e.boss){old.enemyStep(e,dt*(e.slow>0?.55:1));return;}const target=A.active().sort((a,b)=>dist(a,e)-dist(b,e))[0];if(!target||dist(target,e)>1100){e.anim=(e.anim||0)+dt;e.moving=false;return;}const species=S[e.id],kind=species.kind,d=dist(e,target);e.prevX=e.x;e.prevY=e.y;e.anim=(e.anim||0)+dt;e.hurt=Math.max(0,(e.hurt||0)-dt);e.flash=Math.max(0,(e.flash||0)-dt);e.bar+=(e.hp-e.bar)*Math.min(1,dt*7);if(e.stun>0){e.stun-=dt;return;}const speed=e.baseSpeed*(e.slow>0?.5:1),dx=target.x-e.x,dy=target.y-e.y,dd=d||1;e.cd-=dt;e.shotAnim=Math.max(0,(e.shotAnim||0)-dt);A.face(e,dx,dy);let moving=false;
 const ranged=['water','spark','psychic','ghost','poison','leaf','ice','dragon'].includes(kind)&&![98,99,129,130,46,47,10,13].includes(e.id);
 if(e.id===129){A.move(e,-dx/dd*speed*.6*dt,-dy/dd*speed*.6*dt);moving=true;if(e.cd<=0){e.cd=3;A.fx('water',e.x,e.y,1,.5);}}
 else if([35,36,39,40,113,120,121].includes(e.id)&&e.cd<=0){for(const b of A.enemies)if(b.hp>0&&dist(e,b)<250)b.hp=Math.min(b.max,b.hp+b.max*.1);e.cd=7;A.fx('water',e.x,e.y,3,.7);}
 else if(ranged&&d<500&&A.clearLine(e,target)){if(d<170){A.move(e,-dx/dd*speed*.5*dt,-dy/dd*speed*.5*dt);moving=true;}if(e.windup>0){e.windup-=dt;if(e.windup<=0){const n=[121,82,93,94,65,131].includes(e.id)?3:1;for(let i=0;i<n;i++)A.fire(e,e.aimAngle+(i-(n-1)/2)*.2,285,e.damage,kind,e.x,e.y,{level:e.level,effect:kind==='poison'?'poison':kind==='spark'?'stun':''});e.warning=null;e.cd=1.8-Math.min(.55,A.g.floor*.006);e.shotAnim=.35;}}else if(e.cd<=0){e.windup=.55;e.aimAngle=Math.atan2(dy,dx);e.warning={line:true,angle:e.aimAngle};}}
 else{e.warning=null;e.windup=0;const before={x:e.x,y:e.y};if(A.clearLine(e,target)){const boost=[98,99,56,57,58,59].includes(e.id)&&e.cd<.8?1.65:1;A.move(e,dx/dd*speed*dt*boost,dy/dd*speed*dt*boost);if(e.cd<0)e.cd=3;}else{old.enemyStep(e,dt);return;}moving=dist(before,e)>.1;}e.moving=moving;for(const a of A.active())if(dist(a,e)<a.r+e.r)A.damage(a,e.id===129?e.damage*.4:e.damage,kind,e.level);};
A.playerStep=function(a,mask,dt){for(const k of ['sleep','slow','poison','burn','haste','frenzyLeech','trapCooldown','evoFlash'])a[k]=Math.max(0,(a[k]||0)-dt);if(!a.down){a.mp=Math.min(a.maxMp,a.mp+((a.combat>0?.9:2.2)+Math.min(1,a.mpRegen||0))*dt);if((a.poison>0||a.burn>0)&&(a.dotTimer=(a.dotTimer||0)+dt)>=1){a.dotTimer=0;A.damage(a,Math.max(2,a.max*.018),'poison',a.level);}if(a.sleep>0){mask=0;a.action=null;}}const speed=a.speed;a.speed*=a.slow>0?.55:a.haste>0?1.25:1;old.playerStep(a,mask,dt);a.speed=speed;if(a.down)return;
 for(const trap of A.g.traps||[]){if(dist(a,trap)<(a.job==='explorer'?200:95))trap.revealed=true;if(trap.armed&&trap.cool<=0&&dist(a,trap)<27&&a.trapCooldown<=0){trap.revealed=true;trap.cool=5;a.trapCooldown=1.4;switch(trap.kind){case 'spikes':A.damage(a,12+A.g.floor*.45,'rock',Math.round(3+A.g.floor*.72));break;case 'poison':a.poison=7;break;case 'sleep':a.sleep=2.6;a.action=null;break;case 'mana':a.mp=Math.max(0,a.mp-20);break;case 'snare':a.slow=5;break;}playSound('warning');A.toast('Trampa de '+({spikes:'pinchos',poison:'veneno',sleep:'sueño',mana:'drenaje de maná',snare:'lentitud'}[trap.kind]));}}
 if(a.synergies?.includes('Armonía')&&a.combat<=0)for(const b of A.active())if(b!==a&&dist(a,b)<180)b.hp=Math.min(b.max,b.hp+1.5*dt);if(a.synergies?.includes('Fortaleza')){a.synergyClock=(a.synergyClock||0)+dt;if(a.synergyClock>12){a.synergyClock=0;a.shield=Math.max(a.shield,2);}}
};
function systemsStep(dt){for(const ch of channels){ch.life-=dt;ch.tick-=dt;const a=A.players.find(a=>a.pid===ch.owner);if(!a||a.down||a.sleep>0){ch.life=0;continue;}if(ch.tick<=0){ch.tick=.09;for(let i=-1;i<=1;i++)A.fire(a,ch.angle+i*.15,410,ch.damage,'flame',a.x,a.y,{effect:'cone',life:.48,skill:true});}}channels=channels.filter(c=>c.life>0);for(const trap of A.g?.traps||[])trap.cool=Math.max(0,trap.cool-dt);for(const z of zones){z.life-=dt;z.tick-=dt;if(z.tick<=0){z.tick=.7;const owner=A.players.find(a=>a.pid===z.owner);for(const e of A.enemies)if(e.hp>0&&dist(e,z)<z.r&&A.clearLine(z,e)){A.hurt(e,z.damage,owner,{skill:true});if(z.mode==='leech')for(const a of A.active())if(dist(a,z)<220)a.hp=Math.min(a.max,a.hp+z.damage*.35*(owner?.healPower||1));if(z.mode==='snare')e.slow=2;}}}zones=zones.filter(z=>z.life>0);for(const h of helpers){h.life-=dt;h.cool-=dt;h.anim+=dt;const owner=A.players.find(a=>a.pid===h.owner);if(!owner||owner.down){h.life=0;continue;}if(!h.stationary&&dist(h,owner)>120){const dx=owner.x-h.x,dy=owner.y-h.y,d=Math.hypot(dx,dy)||1;A.move(h,dx/d*owner.speed*.8*dt,dy/d*owner.speed*.8*dt);}const e=A.enemies.filter(e=>e.hp>0&&dist(h,e)<600).sort((a,b)=>dist(a,h)-dist(b,h))[0];if(e&&h.cool<=0){h.cool=h.stationary?.65:.9;const ang=Math.atan2(e.y-h.y,e.x-h.x);h.dir=(2-Math.round(ang/(Math.PI/4))+8)%8;A.fire(owner,ang,390,h.damage,S[owner.id].kind,h.x,h.y);}if(h.heals)owner.hp=Math.min(owner.max,owner.hp+dt*1.2);}helpers=helpers.filter(h=>h.life>0);}
A.step=function(dt){if(A.g?.assetLoading){A.clock+=dt;return;}old.step(dt);if(A.g&&A.state==='play'&&!A.g.paused&&A.NET.role!=='client'&&!A.g.ended)systemsStep(dt);};
A.useItem=function(a,key){const it=I[key];if(!it||a.down||!(a.bag[key]>0))return;if(it.type==='use'&&(it.mp||it.cleanse||it.reveal||it.reset||it.teamWake)){if(it.cleanse&&!['poison','sleep','burn','slow'].some(k=>a[k]>0)&&(!it.mp||a.mp>=a.maxMp)&&(!it.heal||a.hp>=a.max)){A.toast('No hay estados que curar.');return;}if(it.reset){if(a.q<=0&&a.e<=0){A.toast('Tus movimientos ya están listos.');return;}a.q=0;a.e=0;}if(it.teamWake&&!A.active().some(b=>dist(a,b)<350&&(b.sleep>0||b.slow>0))){A.toast('No hay aliados dormidos o ralentizados cerca.');return;}if(it.teamWake)for(const b of A.active())if(dist(a,b)<350){b.sleep=0;b.slow=0;}if(it.mp&&a.mp>=a.maxMp&&!it.cleanse&&!it.reset){A.toast('Tu maná ya está completo.');return;}if(it.mp)a.mp=Math.min(a.maxMp,a.mp+it.mp);if(it.heal)a.hp=Math.min(a.max,a.hp+it.heal);if(it.cleanse){a.poison=0;a.sleep=0;a.burn=0;a.slow=0;}if(it.reveal)A.g.stairsKnown=true;a.bag[key]--;A.fx('water',a.x,a.y,2,.5);playSound('heal');}else old.useItem(a,key);};
A.equip=function(a,key){if(!I[key]||I[key].type!=='gear'||!(a.bag[key]>0))return;const index=a.gear.indexOf(key);if(index>=0)a.gear.splice(index,1);else if(I[key].jobs&&!I[key].jobs.includes(a.job)){A.toast('Equipo para '+I[key].jobs.map(j=>C[j].name).join(', ')+'. Puedes entregarlo a un aliado.');return;}else if(a.gear.length<3)a.gear.push(key);else{A.toast('Tienes tres objetos equipados. Quita uno primero.');return;}A.stats(a);playSound('equip');};
function pickup(a,it){if(it.taken||dist(a,it)>90)return;it.taken=true;a.bag[it.key]=(a.bag[it.key]||0)+1;A.toast(a.name+' recogió '+I[it.key].name);playSound('loot');}
